"""SQLAlchemy model for AnalysisResults generated by AI or scientific heuristics."""

from sqlalchemy import Column, String, Float, Text, ForeignKey, JSON, DateTime
from sqlalchemy.orm import relationship
from backend.app.core.database import Base
from backend.app.models.base import TimestampMixin, generate_uuid


class AnalysisResult(Base, TimestampMixin):
    """Stores AI analysis explanations, regime classification, and dimensionless numbers."""

    __tablename__ = "analysis_results"

    id = Column(String(64), primary_key=True, default=generate_uuid, index=True)
    experiment_id = Column(
        String(64),
        ForeignKey("experiments.id", ondelete="CASCADE"),
        nullable=True,
        index=True,
    )
    simulation_id = Column(
        String(64),
        ForeignKey("simulation_results.id", ondelete="SET NULL"),
        nullable=True,
        index=True,
    )

    # Status: PENDING, RUNNING, COMPLETED, FAILED
    status = Column(String(32), default="PENDING", nullable=False, index=True)

    # Executive scientific summary
    summary = Column(Text, nullable=False)

    # Combustion regime classification
    # e.g., "Diffusive Spherical Microgravity", "Buoyant Laminar Convective", "Transitional"
    regime_classification = Column(String(128), nullable=False)

    # Dimensionless numbers dictionary
    # { "richardson_number": float, "grashof_number": float, "froude_number": float, "rayleigh_number": float }
    dimensionless_numbers = Column(JSON, nullable=True)

    # Structured insights and explanations
    scientific_findings = Column(JSON, nullable=True)  # List[str]
    recommendations = Column(JSON, nullable=True)  # List[str]

    # Metrics
    confidence_score = Column(Float, default=1.0, nullable=False)
    ai_model_used = Column(String(128), default="NASA-FLAME Combustion AI v1", nullable=True)

    error_message = Column(Text, nullable=True)
    completed_at = Column(DateTime(timezone=True), nullable=True)

    # Relationships
    experiment = relationship("Experiment", back_populates="analyses")
    simulation = relationship("SimulationResult", back_populates="analyses")

